// SuperMod's hooks: observe the engine's events into `$.state` and keep the
// run and the usage fresh on timers while something is visible (spec §6).
// Parsing and rules live in the pure modules; every `$` call is written out in
// full here, in a hook or in a top-level function that receives `$` (spec §7).
// Every observing hook passes its event on unchanged; only `command.run` for
// `supermod` answers for itself.

import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, Timer, TurnUsage } from 'claude-code'
import type { AgentsState, ContextState, ModelsState, RunFiles, RunState, StoredBreakdown, UiOptions, UiState } from '../types'
import { bandModel, planBandRow, renderBand } from './band'
import { applyFiles, DEFAULT_OPTIONS, finishAgent, isFound, isNewRun, newRow, optionsOf, pathsIn, planKey, reviveAgent, syncAgents, withReferenced, withSnapshot, ZERO } from './glue'
import { t } from './i18n'
import { paneModel, planPane, renderPane, statusText } from './pane'
import { discoverRun, discoverWorktreeRoots, resolveRoots } from './scan'
import type { Fs } from './scan'
import { addModel, addUsage, crossing, pushReading, tone, upsertAgent } from './usage'
import type { Reading } from './usage'
import { isBandVisible } from './visibility'

const USAGE_EVERY_MS = 3_000
const FILES_EVERY_MS = 30_000
const BREAKDOWN_EVERY_MS = 30_000
/** A tool call's run refresh waits this long; calls within it share the one refresh. */
const TOOL_REFRESH_AFTER_MS = 2_000
const MAX_AGE_MS = 7 * 86_400_000
const FINISHING = 'superpowers:finishing-a-development-branch'
const SPEC_FILE = /(?:^|\/)docs\/superpowers\/specs\/[^/]+-design\.md$/

const runAtom = atom({ plugin: 'supermod', key: 'run' } as const, {
  files: null, snapshot: null, skillsSeen: [], sessionSpec: null, pinned: null, lastLedger: null, completions: [],
  startedAt: null, startedWithCompleted: false, finishingTurnCompleted: false, referenced: [],
} as RunState)
const contextAtom = atom({ plugin: 'supermod', key: 'context' } as const, { ring: [], compactions: 0, lastCompactionAt: null, lastTone: 'success', breakdown: null } as ContextState)
const agentsAtom = atom({ plugin: 'supermod', key: 'agents' } as const, { rows: [] } as AgentsState)
const modelsAtom = atom({ plugin: 'supermod', key: 'models' } as const, { totals: {}, engineUsd: null } as ModelsState)
const uiAtom = atom({ plugin: 'supermod', key: 'ui' } as const, { isHidden: false, isPaneOpen: false, surfaces: [], options: DEFAULT_OPTIONS } as UiState)

/** The running timers; a module reload drops them, the state stays. */
let timers: { usage: Timer; files: Timer } | null = null
/** The run refresh a tool call asked for, until it starts. */
let toolRefresh: Timer | null = null

/** Swallows a failure while observing: the event goes on whatever the mod's bookkeeping did. */
async function observe(work: () => Promise<unknown>): Promise<void> {
  try {
    await work()
  } catch {
    // Observing never breaks the event it observes.
  }
}

// ── Adapters, refreshes and timers (the only places `$` is called) ────────

function fsOf($: EngineInterface): Fs {
  return {
    read: p => $.fs.read(p),
    list: p => $.fs.list(p),
    stat: p => $.fs.stat(p, { resolve: true }).then(s => s, () => null),
  }
}

/**
 * Finds the current run in the search roots and stores files, snapshot and
 * completions; files unchanged since the last refresh are not read again, and
 * nothing is written when nothing changed. A new run ends a `[Hide]`.
 */
async function refreshRun($: EngineInterface): Promise<void> {
  const fs = fsOf($)
  const cur = await read($, runAtom)
  const roots = await resolveRoots(fs, await $.session.root())
  // The worktree folders of the main checkout, whether the session sits in it or in one of its worktrees.
  const main = roots[1] ?? roots[0]
  if (main !== undefined) for (const r of await discoverWorktreeRoots(fs, main)) if (!roots.includes(r)) roots.push(r)
  const now = await $.clock.now()
  const opts = { pinned: cur.pinned, sessionSpec: cur.sessionSpec, now, maxAgeMs: MAX_AGE_MS, prior: cur.files }
  let found: RunFiles | null = await discoverRun(fs, roots, opts)
  // The newest-plan route counts only for a plan a tool call named in this session.
  const key = found.planPath === null ? null : planKey(found.planPath)
  if (cur.pinned === null && found.ledgerPath === null && found.planPath !== null && !cur.referenced.some(p => key !== null && planKey(p) === key)) found = null
  if (found !== null && !isFound(found)) found = null
  // Once the workspace is gone, keep following the run's plan rather than falling back to its spec.
  const prev = cur.files
  const isLost = found === null || (found.ledgerPath === null && found.planPath === null && (found.specPath === null || found.specPath === prev?.specPath))
  if (prev?.planPath && isLost) {
    const again = await discoverRun(fs, roots, { ...opts, pinned: prev.planPath })
    if (again.planPath === prev.planPath) found = again
  }
  if (applyFiles(cur, found, now) === cur) return
  if (isNewRun(cur, found) && (await read($, uiAtom)).isHidden) await update($, uiAtom, u => ({ ...u, isHidden: false }))
  await update($, runAtom, c => applyFiles(c, found, now))
}

/** One run refresh shortly after a tool call named a run path, outside the call: the result never waits for it, a burst of calls shares it. */
function refreshRunSoon($: EngineInterface, o: UiOptions): void {
  if (toolRefresh !== null) return
  toolRefresh = $.clock.after(TOOL_REFRESH_AFTER_MS, () => {
    toolRefresh = null
    void tick($, o, () => refreshRun($))
  })
}

/** Reads the main context; a new reading goes into the ring and may raise one toast. */
async function refreshContext($: EngineInterface, o: UiOptions): Promise<void> {
  const usage = await $.session.usage()
  const now = await $.clock.now()
  const reading: Reading = { at: now, percent: usage.context.percent ?? null, tokens: usage.context.tokens ?? null, window: usage.context.window }
  const engineUsd = usage.cost?.usd ?? null
  const models = await read($, modelsAtom)
  if (models.engineUsd !== engineUsd) await update($, modelsAtom, m => ({ ...m, engineUsd }))
  const last = (await read($, contextAtom)).ring.at(-1)
  if (last && last.percent === reading.percent && last.tokens === reading.tokens && last.window === reading.window) return
  let raised = null as 'warn' | 'critical' | null
  await update($, contextAtom, c => {
    raised = crossing(c.ring.at(-1)?.percent ?? null, reading.percent, o.warnPercent, o.criticalPercent)
    return { ...c, ring: pushReading(c.ring, reading), lastTone: tone(reading.percent, o.warnPercent, o.criticalPercent) }
  })
  if (raised !== null && reading.percent !== null) {
    $.ui.toast(t(o.language, raised === 'warn' ? 'toast.warn' : 'toast.critical').replace('{p}', String(reading.percent)))
  }
}

/** The `/context`-style rows while the pane is open, at most every 30 s; dropped once it closes. */
async function refreshBreakdown($: EngineInterface): Promise<void> {
  const isPaneOpen = (await read($, uiAtom)).isPaneOpen
  const cur = (await read($, contextAtom)).breakdown ?? null
  if (!isPaneOpen) {
    if (cur !== null) await update($, contextAtom, c => ({ ...c, breakdown: null }))
    return
  }
  const now = await $.clock.now()
  if (cur !== null && now - cur.at < BREAKDOWN_EVERY_MS) return
  const bd = (await $.session.usage({ breakdown: 'summary' })).context.breakdown
  // None without a bound session: an empty one still waits out the 30 s.
  const breakdown: StoredBreakdown = {
    at: now,
    maxTokens: bd?.maxTokens ?? 0,
    categories: (bd?.categories ?? []).map(c => ({ name: c.name, tokens: c.tokens, kind: c.kind })),
  }
  await update($, contextAtom, c => ({ ...c, breakdown }))
}

/** Whether the pane is open, the context (and its breakdown while open), and the engine's agent statuses; a failed part skips no other. */
async function refreshUsage($: EngineInterface, o: UiOptions): Promise<void> {
  await observe(async () => {
    const isPaneOpen = (await $.ui.panes()).some(p => p.id === 'supermod' && p.isShown)
    if ((await read($, uiAtom)).isPaneOpen !== isPaneOpen) await update($, uiAtom, u => ({ ...u, isPaneOpen }))
  })
  await observe(() => refreshContext($, o))
  await observe(() => refreshBreakdown($))
  await observe(async () => {
    const now = await $.clock.now()
    const listed = await $.agent.list()
    const rows = (await read($, agentsAtom)).rows
    if (syncAgents(rows, listed, now) !== rows) await update($, agentsAtom, a => ({ rows: syncAgents(a.rows, listed, now) }))
  })
}

/** Usage, run, then the timers, each on its own so one failure skips none of the others. */
async function refreshAll($: EngineInterface, o: UiOptions): Promise<void> {
  await observe(() => refreshUsage($, o))
  await observe(() => refreshRun($))
  await observe(() => syncTimers($, o))
}

/** Adds one model response's usage to its model's totals and, for a subagent, to its row. */
async function recordStep($: EngineInterface, agentId: string | null, u: TurnUsage): Promise<void> {
  await update($, modelsAtom, m => ({ ...m, totals: addModel(m.totals, u.model, addUsage(ZERO, u)) }))
  if (agentId === null) return
  const now = await $.clock.now()
  const lastWindow = u.input_tokens + u.cache_read_input_tokens + u.cache_creation_input_tokens
  await update($, agentsAtom, a => {
    const row = reviveAgent(a.rows.find(r => r.id === agentId) ?? newRow(agentId, now))
    return { rows: upsertAgent(a.rows, { ...row, model: u.model, usage: addUsage(row.usage, u), lastWindow, steps: row.steps + 1 }) }
  })
}

function startTimers($: EngineInterface, o: UiOptions): void {
  if (timers !== null) return
  timers = {
    usage: $.clock.every(USAGE_EVERY_MS, () => void tick($, o, () => refreshUsage($, o))),
    files: $.clock.every(FILES_EVERY_MS, () => void tick($, o, () => refreshRun($))),
  }
}

function stopTimers(): void {
  timers?.usage.cancel()
  timers?.files.cancel()
  timers = null
}

async function tick($: EngineInterface, o: UiOptions, work: () => Promise<void>): Promise<void> {
  await observe(work)
  await observe(() => syncTimers($, o))
}

/** Timers run only while the band is visible or the pane is open. */
async function syncTimers($: EngineInterface, o: UiOptions): Promise<void> {
  const ui = await read($, uiAtom)
  const visible = isBandVisible({ run: await read($, runAtom), context: await read($, contextAtom), ui }, o)
  if (visible || ui.isPaneOpen) startTimers($, o)
  else stopTimers()
}

// ── Hooks ─────────────────────────────────────────────────────────────────

export const register: Register = (on, options) => {
  const o = optionsOf(options)

  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'supermod',
      description: 'Show Superpowers progress, context fill and agents',
    })
    await observe(async () => {
      const surfaces = await $.session.surfaces()
      await update($, uiAtom, u => ({ ...u, surfaces: [...surfaces] }))
    })
    await observe(() => update($, uiAtom, u => ({ ...u, options: o })))
    await refreshAll($, o)
    return next(e)
  })

  // `/supermod`: no argument opens the pane; hide, show, status, use <path>, use auto.
  on('command.run', { command: 'supermod' }, async ($, e) => {
    const [verb = '', ...rest] = e.args.trim().split(/\s+/)
    const arg = rest.join(' ')
    if (verb === 'hide' || verb === 'show') {
      await update($, uiAtom, u => ({ ...u, isHidden: verb === 'hide' }))
      await observe(() => syncTimers($, o))
      return { text: t(o.language, verb === 'hide' ? 'hidden' : 'shown') }
    }
    if (verb === 'status') {
      const state = { run: await read($, runAtom), context: await read($, contextAtom), agents: await read($, agentsAtom), ui: await read($, uiAtom) }
      return { text: statusText(state, o) }
    }
    if (verb === 'use' && arg !== '') {
      const pinned = arg === 'auto' ? null : arg.startsWith('/') ? arg : `${(await $.session.root()).replace(/\/+$/, '')}/${arg.replace(/^\.\//, '')}`
      await update($, runAtom, c => ({ ...c, pinned }))
      await observe(() => refreshRun($))
      await observe(() => syncTimers($, o))
      return { text: pinned === null ? t(o.language, 'unpinned') : t(o.language, 'pinned').replace('{p}', pinned) }
    }
    const opened = await $.ui.open({ id: 'supermod', title: 'SuperMod' })
    await update($, uiAtom, u => ({ ...u, isPaneOpen: true }))
    await observe(() => syncTimers($, o))
    return { text: t(o.language, opened.isPlaced ? 'paneOpened' : 'surfaceFallback') }
  })

  // The pane reads state and the clock only; the command and the timers write.
  on('ui.render', { component: 'Pane', requestId: 'supermod' }, async ($, e) => {
    const state = {
      run: await read($, runAtom), context: await read($, contextAtom), agents: await read($, agentsAtom), models: await read($, modelsAtom), ui: await read($, uiAtom),
    }
    const model = paneModel(state, o, await $.clock.now())
    return renderPane($.ui.resolve(e), planPane(model, e.props.bodyColumns, e.props.scroll.bodyRows))
  })

  // The band reads state only; its buttons write from their own presses.
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey) return next(e)
    const state = { run: await read($, runAtom), context: await read($, contextAtom), agents: await read($, agentsAtom), ui: await read($, uiAtom) }
    const model = bandModel(state)
    if (model === null) return next(e)
    return renderBand($.ui.resolve(e), planBandRow(model, e.props.bodyColumns), {
      onDetails: async () => {
        await $.ui.open({ id: 'supermod', title: 'SuperMod' })
        await update($, uiAtom, u => ({ ...u, isPaneOpen: true }))
        await observe(() => syncTimers($, o))
      },
      onHide: async () => {
        await update($, uiAtom, u => ({ ...u, isHidden: true }))
        await observe(() => syncTimers($, o))
      },
    })
  })

  on('skill.prompt', async ($, e, next) => {
    const r = await next(e)
    if (e.skill.startsWith('superpowers:')) {
      await observe(() => update($, runAtom, c => (c.skillsSeen.includes(e.skill) ? c : withSnapshot({ ...c, skillsSeen: [...c.skillsSeen, e.skill] }))))
      await observe(() => syncTimers($, o))
    }
    return r
  })

  on('tool.call', async ($, e, next) => {
    const input = e as unknown as Record<string, unknown>
    const paths = pathsIn(input)
    const r = await next(e)
    if (paths.length > 0) {
      const file = input.file_path
      const spec = (e.tool === 'Write' || e.tool === 'Edit') && typeof file === 'string' && SPEC_FILE.test(file) ? file : null
      await observe(async () => {
        const c = await read($, runAtom)
        if (withReferenced(c, paths, spec) !== c) await update($, runAtom, r => withReferenced(r, paths, spec))
      })
      await observe(async () => refreshRunSoon($, o))
    }
    return r
  })

  on('turn.step', async function* ($, e, next) {
    const r = yield* next(e)
    const usage = r.usage
    if (usage) await observe(() => recordStep($, e.agentId ?? null, usage))
    if (e.agentId === undefined) await observe(() => refreshContext($, o))
    return r
  })

  on('turn.complete', async ($, e, next) => {
    const r = await next(e)
    if (e.agentId === undefined) {
      // Written only when it changes: `update` writes whatever its function returns.
      await observe(async () => {
        const c = await read($, runAtom)
        if (c.skillsSeen.includes(FINISHING) && !c.finishingTurnCompleted) await update($, runAtom, r => withSnapshot({ ...r, finishingTurnCompleted: true }))
      })
    } else {
      // A subagent's answer is its own turn.complete: its row is done, whatever the engine still lists.
      const id = e.agentId
      await observe(async () => {
        const now = await $.clock.now()
        const rows = (await read($, agentsAtom)).rows
        if (finishAgent(rows, id, now) !== rows) await update($, agentsAtom, a => ({ rows: finishAgent(a.rows, id, now) }))
      })
    }
    await refreshAll($, o)
    return r
  })

  on('agent.spawn', async ($, e, next) => {
    const r = await next(e)
    const id = r.agentId
    if (id !== undefined) {
      await observe(async () => {
        const now = await $.clock.now()
        await update($, agentsAtom, a => {
          const row = a.rows.find(x => x.id === id) ?? newRow(id, now)
          return { rows: upsertAgent(a.rows, { ...row, type: e.subagentType, description: e.description, model: row.model ?? r.model }) }
        })
      })
    }
    return r
  })

  on('session.compact', async ($, e, next) => {
    const r = await next(e)
    const skipped = 'skip' in r && typeof r.skip === 'string'
    if (e.agentId === undefined && e.trigger !== 'precompute' && !skipped) {
      await observe(async () => {
        const now = await $.clock.now()
        await update($, contextAtom, c => ({ ...c, compactions: c.compactions + 1, lastCompactionAt: now }))
      })
    }
    return r
  })
}

files.hooks/band.tsx:
// The band above the prompt (spec §4.1): a model from the state, one row
// planned against the band's width, and the tree drawn from that plan. Pure:
// no `$` here; register.tsx resolves the surface's elements and builds the
// handlers with its own calls. JSX compiles to the global `h`; no name here shadows it.

import type { ElementTable, RenderElement } from 'claude-code'
import type { AgentsState, ContextState, RunState, UiState } from '../types'
import { estimateRange } from './eta'
import { bar, fit, pct } from './format'
import { t } from './i18n'
import type { LabelKey, Lang } from './i18n'
import { slugFromFileName } from './progress'
import { tone } from './usage'
import { isBandVisible, isRunActive } from './visibility'

export type BandModel = {
  title: string | null
  percent: number | null
  task: string | null
  station: string | null
  ctxPercent: number | null
  ctxTone: 'success' | 'warning' | 'error'
  agentsRunning: number
  eta: string | null
  lang: Lang
}
export type BandState = { run: RunState; context: ContextState; agents: AgentsState; ui: UiState }
export type Segment = { text: string; tone?: string; bold?: boolean; dim?: boolean }
/** The planned row; `lang` names the buttons. */
export type BandRow = { segments: Segment[]; lang: Lang }
export type BandHandlers = { onDetails: () => unknown; onHide: () => unknown }

const MINUTE_MS = 60_000
const SEP = '  '
/** The title is truncated down to this many cells before it is dropped. */
const TITLE_MIN = 8
const LIVE = new Set(['running', 'pending'])
/** What goes first when the row is too wide (spec §4.1). */
const DROPS = ['eta', 'agents', 'station', 'title'] as const

type GroupId = 'lead' | 'title' | 'progress' | 'task' | (typeof DROPS)[number] | 'ctx'
/** Segments that stay or go together, `sep` in front of them unless they lead the row. */
type Group = { id: GroupId; sep: string; parts: Segment[] }

/** The band's content, or null when it yields (spec §4.1 visibility). */
export function bandModel(s: BandState): BandModel | null {
  return isBandVisible(s, s.ui.options) ? bandModelOf(s) : null
}

/** The band's content whether the band is visible or not (the status text answers either way). */
export function bandModelOf(s: BandState): BandModel {
  const o = s.ui.options
  const lang = o.language
  const ctxPercent = s.context.ring.at(-1)?.percent ?? null
  const base = { ctxPercent, ctxTone: tone(ctxPercent, o.warnPercent, o.criticalPercent), lang }
  const agentsRunning = s.agents.rows.filter(r => LIVE.has(r.status)).length
  const snap = isRunActive(s.run) ? s.run.snapshot : null
  if (snap === null) return { ...base, title: null, percent: null, task: null, station: null, agentsRunning, eta: null }
  const plan = s.run.files?.planPath ?? null
  const cur = snap.currentTask
  const range = estimateRange(s.run.completions, s.run.startedWithCompleted ? null : s.run.startedAt, snap.total - snap.completed, o.reviewMinutes)
  return {
    ...base,
    title: plan !== null ? slugFromFileName(plan.slice(plan.lastIndexOf('/') + 1)) : snap.title || null,
    percent: snap.percent,
    task: cur === null ? null : `${t(lang, 'task')} ${cur.n}/${snap.total}`,
    station: cur === null || cur.station === 'none' ? null : t(lang, `station.${cur.station}` as LabelKey),
    agentsRunning,
    eta: range === null ? null : `~${Math.round(range.lowMs / MINUTE_MS)}–${Math.round(range.highMs / MINUTE_MS)} ${t(lang, 'min')}`,
  }
}

/** Cells the two buttons take on the terminal (`[ label ]` each) with a space before each. */
export function buttonCells(lang: Lang): number {
  return 1 + t(lang, 'details').length + 4 + 1 + t(lang, 'hide').length + 4
}

function groupsOf(m: BandModel, isWide: boolean): Group[] {
  const g: Group[] = []
  const label = (key: LabelKey): Segment => ({ text: t(m.lang, key) + ' ', dim: true })
  if (m.title !== null) g.push({ id: 'title', sep: SEP, parts: [{ text: m.title }] })
  else g.push({ id: 'lead', sep: SEP, parts: [{ text: t(m.lang, 'title'), dim: true }] })
  if (m.percent !== null) g.push({ id: 'progress', sep: SEP, parts: [{ text: bar(m.percent, isWide ? 12 : 6) }, { text: ' ' + pct(m.percent), bold: true }] })
  if (m.task !== null) g.push({ id: 'task', sep: SEP, parts: [{ text: m.task }] })
  if (m.task !== null && m.station !== null) g.push({ id: 'station', sep: ' · ', parts: [{ text: m.station, dim: true }] })
  g.push({
    id: 'ctx',
    sep: SEP,
    parts: [label('ctx'), { text: bar(m.ctxPercent, isWide ? 8 : 6), tone: m.ctxTone }, { text: ' ' + pct(m.ctxPercent), tone: m.ctxTone, bold: true }],
  })
  if (m.percent !== null) g.push({ id: 'agents', sep: SEP, parts: [label('agents'), { text: String(m.agentsRunning) }] })
  if (m.eta !== null) g.push({ id: 'eta', sep: SEP, parts: [{ text: m.eta }] })
  return g
}

/** Cells the groups take, the title counted as `titleCells`. */
function widthOf(groups: Group[], titleCells: number): number {
  return groups.reduce((sum, g, i) => {
    const sep = i === 0 ? 0 : g.sep.length
    return sum + sep + (g.id === 'title' ? titleCells : g.parts.reduce((s, p) => s + p.text.length, 0))
  }, 0)
}

const titleOf = (groups: Group[]) => groups.find(g => g.id === 'title')?.parts[0].text ?? ''

/** The row's segments, separators folded into the text, ending before the buttons. */
function flatten(groups: Group[], titleCells: number): Segment[] {
  return groups.flatMap((g, i) => {
    const parts = g.id === 'title' ? [{ ...g.parts[0], text: fit(g.parts[0].text, titleCells) }] : g.parts
    return i === 0 ? parts : [{ ...parts[0], text: g.sep + parts[0].text }, ...parts.slice(1)]
  })
}

/** Cuts the row at `budget` cells, the last segment ending in an ellipsis. */
export function clip(segments: Segment[], budget: number): Segment[] {
  const out: Segment[] = []
  let left = Math.max(0, budget)
  for (const s of segments) {
    if (left === 0) break
    if (s.text.length <= left) {
      out.push(s)
      left -= s.text.length
    } else {
      out.push({ ...s, text: fit(s.text, left) })
      left = 0
    }
  }
  return out
}

/**
 * The band's row for `columns` cells beside the buttons: the full row with
 * 12/8-cell bars, else with 6/6-cell bars, then dropping time range, agents,
 * station, title in that order until it fits; whatever is left is cut.
 */
export function planBandRow(m: BandModel, columns: number): BandRow {
  const budget = columns - buttonCells(m.lang)
  const fits = (gs: Group[]) => widthOf(gs, Math.min(TITLE_MIN, titleOf(gs).length)) <= budget
  const wide = groupsOf(m, true)
  let groups = fits(wide) ? wide : groupsOf(m, false)
  for (const id of DROPS) {
    if (fits(groups)) break
    groups = groups.filter(g => g.id !== id)
  }
  const title = titleOf(groups)
  const titleCells = Math.min(title.length, budget - widthOf(groups, 0))
  return { segments: clip(flatten(groups, titleCells), budget), lang: m.lang }
}

/** A segment's Text props: its tone, `subtle` for a label, bold for a value; no prop left undefined. */
export function styleOf(s: Segment): { color?: string; bold?: boolean } {
  const color = s.tone ?? (s.dim ? 'subtle' : null)
  return { ...(color !== null ? { color } : {}), ...(s.bold ? { bold: true } : {}) }
}

/** The band: one row of the planned segments, then `[Details]` and `[Hide]`. */
export function renderBand(els: ElementTable, row: BandRow, handlers: BandHandlers): RenderElement {
  const { Box, Button, Text } = els
  return (
    <Box flexDirection="row">
      {row.segments.map(s => (
        <Text {...styleOf(s)}>{s.text}</Text>
      ))}
      <Box flexDirection="row" marginLeft={1} gap={1}>
        <Button key="details" label={t(row.lang, 'details')} onPress={handlers.onDetails} />
        <Button key="hide" label={t(row.lang, 'hide')} onPress={handlers.onHide} />
      </Box>
    </Box>
  )
}

files.hooks/glue.ts:
// The pure glue between the engine's events and the state: options, run-file
// bookkeeping, agent rows and the run snapshot. No `$` here; register.tsx
// calls these from its hooks, refreshes and timers.

import type { PluginOptions } from 'claude-code'
import type { RunFiles, RunState, StoredLedger, StoredPlan, UiOptions } from '../types'
import { recordCompletions } from './eta'
import { computeRun } from './progress'
import type { Ledger, Plan, RunSnapshot } from './progress'
import { upsertAgent } from './usage'
import type { AgentRow, Usage } from './usage'

const FINISHED = new Set(['completed', 'failed', 'killed'])
export const ZERO: Usage = { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 }
/** What ends a path inside a tool input: whitespace, quotes, brackets and shell operators. */
const DELIMITERS = /[\s'"`<>()|;&]+/
/** The part every run path holds: workspace, ledger, marker, plan or spec. */
const RUN_PART = /\.superpowers\/sdd\/|docs\/superpowers\/(?:plans|specs)\//
/** Input scanned per field, and the longest run path kept. */
const SCAN_CAP = 100_000
const PATH_CAP = 512
/** Run paths kept from this session's tool calls. */
const REFERENCED_CAP = 100
export const DEFAULT_OPTIONS: UiOptions = { language: 'en', warnPercent: 70, criticalPercent: 85, showCost: true, reviewMinutes: 10 }

export function optionsOf(o: PluginOptions): UiOptions {
  const num = (v: unknown, d: number) => (typeof v === 'number' && Number.isFinite(v) ? v : d)
  return {
    language: o.language === 'de' ? 'de' : 'en',
    warnPercent: num(o.warnPercent, DEFAULT_OPTIONS.warnPercent),
    criticalPercent: num(o.criticalPercent, DEFAULT_OPTIONS.criticalPercent),
    showCost: typeof o.showCost === 'boolean' ? o.showCost : DEFAULT_OPTIONS.showCost,
    reviewMinutes: num(o.reviewMinutes, DEFAULT_OPTIONS.reviewMinutes),
  }
}

export const loadLedger = (s: StoredLedger): Ledger => ({ planPath: s.planPath, tasks: new Map(s.tasks.map(x => [x.n, x])) })
export const loadPlan = (p: StoredPlan): Plan => ({ title: p.title, specPath: p.specPath, taskCount: p.tasks.length, taskTitles: new Map(p.tasks.map(x => [x.n, x.title])) })
export const isFound = (f: RunFiles) => f.ledgerPath !== null || f.planPath !== null || f.specPath !== null || f.workspaceExists
const same = (a: string | null | undefined, b: string | null | undefined) => a != null && a === b
export const sameRun = (a: RunFiles, b: RunFiles) =>
  same(a.planPath, b.planPath) || same(a.specPath, b.specPath) || same(a.ledgerPath, b.ledgerPath) || same(a.workspaceDir, b.workspaceDir)
/** Whether a discovery found another run than the state holds (or the first one). */
export const isNewRun = (c: RunState, found: RunFiles | null) => found !== null && (c.files === null || !sameRun(c.files, found))
export const planKey = (p: string) => (p.includes('docs/superpowers/plans/') ? p.slice(p.lastIndexOf('docs/superpowers/plans/')) : null)

/**
 * Run paths named in a tool call's file path, path, command or prompt: in each
 * token between delimiters that holds a run part, from just after the last `=`
 * before that part to the token's end. Linear in the input: the part is found
 * by plain search, never by a pattern that backtracks over the token; a path
 * longer than 512 characters is dropped.
 */
export function pathsIn(e: Record<string, unknown>): string[] {
  const out = new Set<string>()
  for (const key of ['file_path', 'path', 'command', 'prompt']) {
    const v = e[key]
    if (typeof v !== 'string') continue
    for (const token of v.slice(0, SCAN_CAP).split(DELIMITERS)) {
      if (!token.includes('superpowers/')) continue
      const at = token.search(RUN_PART)
      if (at < 0) continue
      const path = token.slice(token.lastIndexOf('=', at) + 1)
      if (path.length > PATH_CAP) continue
      out.add(path.replace(/^\.\//, '').replace(/[.,:;]+$/, ''))
    }
  }
  return [...out]
}

/** The state with the paths a tool call named moved to the end (the last 100 kept) and the spec it wrote; `c` itself when nothing changes. */
export function withReferenced(c: RunState, paths: string[], spec: string | null): RunState {
  const referenced = [...c.referenced.filter(p => !paths.includes(p)), ...paths].slice(-REFERENCED_CAP)
  const sessionSpec = spec ?? c.sessionSpec
  const isSame = sessionSpec === c.sessionSpec && referenced.length === c.referenced.length && referenced.every((p, i) => p === c.referenced[i])
  return isSame ? c : { ...c, referenced, sessionSpec }
}

export const newRow = (id: string, now: number): AgentRow => ({
  id, type: '', description: '', status: 'running', model: null, startedAt: now, endedAt: null, usage: ZERO, lastWindow: 0, steps: 0,
})

/** Rows with the engine's statuses applied, and rows for agents the mod has not seen spawn. */
export function syncAgents(rows: AgentRow[], listed: readonly { id: string; type: string; description: string; status: string }[], now: number): AgentRow[] {
  let next = rows
  for (const a of listed) {
    const row = next.find(r => r.id === a.id) ?? { ...newRow(a.id, now), type: a.type, description: a.description }
    // A closed row stays closed while the engine still lists its agent as live: only a new step of the agent revives it.
    if (row.endedAt !== null && !FINISHED.has(a.status)) continue
    if (row.status === a.status && next.includes(row)) continue
    const endedAt = FINISHED.has(a.status) ? row.endedAt ?? now : row.endedAt
    next = upsertAgent(next, { ...row, status: a.status, endedAt })
  }
  // The engine drops an agent's entry once its task is over: a row it no longer lists is finished.
  // Only rows older than `now` (taken before the list call) count; one spawned meanwhile is not missing.
  const ids = new Set(listed.map(a => a.id))
  for (const row of next) if (!ids.has(row.id) && row.startedAt < now) next = finishAgent(next, row.id, now)
  return next
}

/** The row as a live one again: a closed agent that steps is working. */
export function reviveAgent(row: AgentRow): AgentRow {
  return row.endedAt === null && !FINISHED.has(row.status) ? row : { ...row, status: 'running', endedAt: null }
}

/** The row closed as `completed` at `now`; the same rows when the id is unknown or the row is finished already. */
export function finishAgent(rows: AgentRow[], id: string, now: number): AgentRow[] {
  const row = rows.find(r => r.id === id)
  if (row === undefined || row.endedAt !== null || FINISHED.has(row.status)) return rows
  return upsertAgent(rows, { ...row, status: 'completed', endedAt: now })
}

/** The run as the band and pane draw it, from the stored files and what this session saw. */
export function snapshotOf(r: RunState): RunSnapshot | null {
  const f = r.files
  if (f === null && r.skillsSeen.length === 0) return null
  return computeRun({
    skillsSeen: new Set(r.skillsSeen),
    specExists: f?.specPath != null,
    planExists: f?.planPath != null,
    ledger: f?.ledger != null ? loadLedger(f.ledger) : null,
    workspaceExists: f?.workspaceExists ?? false,
    files: f?.workspaceFiles ?? [],
    plan: f?.plan != null ? loadPlan(f.plan) : null,
    finishingTurnCompleted: r.finishingTurnCompleted,
    lastLedger: r.lastLedger === null ? null : loadLedger(r.lastLedger),
    ...(f?.specTitle != null ? { specTitle: f.specTitle } : {}),
  })
}

export const withSnapshot = (r: RunState): RunState => ({ ...r, snapshot: snapshotOf(r) })

/**
 * The run state after a discovery (`found` null: nothing found, the last files
 * stay): a new run resets the run's clock, a ledger adds completions. Returns
 * `c` itself when nothing changed, so the caller can skip the write and the
 * band is not drawn again (spec §4.1).
 */
export function applyFiles(c: RunState, found: RunFiles | null, now: number): RunState {
  const files = found ?? c.files
  let next: RunState = { ...c, files }
  if (files !== null) {
    const isNew = isNewRun(c, found)
    if (isNew) next = { ...next, startedAt: now, completions: [], lastLedger: null, startedWithCompleted: false }
    if (files.ledger != null) {
      const done = files.ledger.tasks.filter(x => x.complete).map(x => x.n)
      next = { ...next, lastLedger: files.ledger, completions: recordCompletions(next.completions, done, now) }
      if (isNew) next.startedWithCompleted = done.length > 0
    }
  }
  next = withSnapshot(next)
  return JSON.stringify(next) === JSON.stringify(c) ? c : next
}

files.hooks/pane.tsx:
// The detail pane (spec §4.2) and the one-line status (§4.3): a model from the
// state, rows planned against the pane's width, and the tree drawn from that
// plan. Pure: no `$` here; register.tsx reads the state, the clock and the
// surface's elements with its own calls. JSX compiles to the global `h`.

import type { ElementTable, RenderElement } from 'claude-code'
import type { AgentRow, ModelsState, RunSnapshot, UiOptions } from '../types'
import { bandModelOf, clip, planBandRow, styleOf } from './band'
import type { BandState, Segment } from './band'
import { estimateRange, medianMs, taskDurations } from './eta'
import { bar, dur, hm, k, pct, spark, usd } from './format'
import { t } from './i18n'
import type { LabelKey, Lang } from './i18n'
import { slugFromFileName } from './progress'
import { agentContextPercent, estimateUsd, tone } from './usage'
import { isRunActive } from './visibility'

export type PaneState = BandState & { models: ModelsState }

type Tone = 'success' | 'warning' | 'error'

export type PaneAgent = {
  mark: string
  status: string
  type: string
  model: string
  ctxPercent: number | null
  tokensIn: number
  tokensOut: number
  elapsedMs: number
  isFinished: boolean
}

export type PaneModel = {
  lang: Lang
  run: {
    title: string
    path: string | null
    percent: number
    startedAt: number | null
    elapsedMs: number | null
    steps: RunSnapshot['steps']
    current: { n: number; title: string; station: string | null } | null
    eta: { lowMs: number; highMs: number; perTaskMs: number } | null
  } | null
  context: {
    percent: number | null
    tokens: number | null
    window: number | null
    tone: Tone
    warn: number
    critical: number
    spark: string
    compactions: number
    lastCompactionAt: number | null
    breakdown: { name: string; percent: number }[]
  }
  /** Newest first. */
  agents: PaneAgent[]
  running: number
  /** Null when the `showCost` option is off. */
  cost: {
    usd: number
    isEngine: boolean
    models: { name: string; input: number; output: number; cacheRead: number; cacheWrite: number; usd: number }[]
    cacheHit: number | null
  } | null
}

const MINUTE_MS = 60_000
const BREAKDOWN_ROWS = 6
/** Rows the pane keeps for everything but the agent list. */
const NON_AGENT_ROWS = 20
const FINISHED = new Set(['completed', 'failed', 'killed'])
const LIVE = new Set(['running', 'pending'])
const MARKS: Record<string, string> = { running: '●', pending: '○', completed: '✓', failed: '✗', killed: '✗' }
const STEP_MARKS = { done: '✓', active: '▶', pending: '·' } as const
const MODEL_NAMES: Record<string, string> = {
  'claude-opus-5-5': 'Opus 5.5',
  'claude-sonnet-5-5': 'Sonnet 5.5',
  'claude-haiku-5-5': 'Haiku 5.5',
  'fable': 'Fable',
}
/** Cells of an agent row besides its type: mark, status, model, ctx, tokens, elapsed and the gaps. */
const AGENT_FIXED = 2 + 8 + 1 + 1 + 10 + 1 + 4 + 1 + 8 + 1 + 6
const ZERO_USAGE = { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 }

/** `claude-sonnet-5-5` → `Sonnet 5.5`; an unknown id without its `claude-` prefix. */
export function modelShort(id: string | null): string {
  if (id === null) return '–'
  return MODEL_NAMES[id] ?? id.replace(/^claude-/, '')
}

const statusLabel = (lang: Lang, status: string) =>
  status in MARKS ? t(lang, `agent.${status}` as LabelKey) : status

function agentOf(r: AgentRow, lang: Lang, window: number, now: number): PaneAgent {
  const isFinished = r.endedAt !== null || FINISHED.has(r.status)
  return {
    mark: MARKS[r.status] ?? (isFinished ? '✓' : '·'),
    status: statusLabel(lang, r.status),
    type: r.type || r.description || r.id,
    model: modelShort(r.model),
    ctxPercent: agentContextPercent(r, window, null),
    tokensIn: r.usage.input + r.usage.cacheRead + r.usage.cacheWrite,
    tokensOut: r.usage.output,
    elapsedMs: (r.endedAt ?? now) - r.startedAt,
    isFinished,
  }
}

/** The pane's content from the state; `options` are the mod's, `now` the engine's clock. */
export function paneModel(s: PaneState, o: UiOptions, now: number): PaneModel {
  const lang = o.language
  const last = s.context.ring.at(-1)
  const ctxPercent = last?.percent ?? null
  const bd = s.context.breakdown ?? null
  const context: PaneModel['context'] = {
    percent: ctxPercent,
    tokens: last?.tokens ?? null,
    window: last?.window ?? null,
    tone: tone(ctxPercent, o.warnPercent, o.criticalPercent),
    warn: o.warnPercent,
    critical: o.criticalPercent,
    spark: spark(s.context.ring.map(r => r.percent)),
    compactions: s.context.compactions,
    lastCompactionAt: s.context.lastCompactionAt,
    breakdown: bd === null || bd.maxTokens <= 0
      ? []
      : bd.categories.filter(c => c.kind !== 'deferred').slice(0, BREAKDOWN_ROWS).map(c => ({ name: c.name, percent: Math.round((c.tokens / bd.maxTokens) * 100) })),
  }

  const indexed = s.agents.rows.map((r, i) => ({ r, i }))
  indexed.sort((a, b) => b.r.startedAt - a.r.startedAt || b.i - a.i)
  const agents = indexed.map(({ r }) => agentOf(r, lang, last?.window ?? 0, now))
  const running = s.agents.rows.filter(r => LIVE.has(r.status)).length

  let cost: PaneModel['cost'] = null
  if (o.showCost) {
    const entries = Object.entries(s.models.totals)
    const sum = entries.reduce((a, [, u]) => ({ input: a.input + u.input, output: a.output + u.output, cacheRead: a.cacheRead + u.cacheRead, cacheWrite: a.cacheWrite + u.cacheWrite }), ZERO_USAGE)
    const seen = sum.input + sum.cacheRead + sum.cacheWrite
    cost = {
      usd: s.models.engineUsd ?? estimateUsd(s.models.totals),
      isEngine: s.models.engineUsd !== null,
      models: entries.map(([id, u]) => ({
        name: modelShort(id), input: u.input, output: u.output, cacheRead: u.cacheRead, cacheWrite: u.cacheWrite, usd: estimateUsd({ [id]: u }),
      })),
      cacheHit: seen > 0 ? Math.round((sum.cacheRead / seen) * 100) : null,
    }
  }

  const snap = isRunActive(s.run) ? s.run.snapshot : null
  if (snap === null) return { lang, run: null, context, agents, running, cost }
  const f = s.run.files
  const abs = f?.planPath ?? f?.specPath ?? f?.ledgerPath ?? null
  const path = abs !== null && f?.root && abs.startsWith(f.root + '/') ? abs.slice(f.root.length + 1) : abs
  const since = s.run.startedWithCompleted ? null : s.run.startedAt
  const range = estimateRange(s.run.completions, since, snap.total - snap.completed, o.reviewMinutes)
  const cur = snap.currentTask
  return {
    lang,
    run: {
      title: snap.title || (abs !== null ? slugFromFileName(abs.slice(abs.lastIndexOf('/') + 1)) : t(lang, 'title')),
      path,
      percent: snap.percent,
      startedAt: s.run.startedAt,
      elapsedMs: s.run.startedAt === null ? null : now - s.run.startedAt,
      steps: snap.steps,
      current: cur === null ? null : { n: cur.n, title: cur.title, station: cur.station === 'none' ? null : t(lang, `station.${cur.station}` as LabelKey) },
      eta: range === null ? null : { ...range, perTaskMs: medianMs(taskDurations(s.run.completions, since)) },
    },
    context,
    agents,
    running,
    cost,
  }
}

const minutes = (ms: number) => Math.round(ms / MINUTE_MS)

/** The pane's rows for `columns` cells, the agent list capped to `rows - 20`; no row wider than `columns`. */
export function planPane(m: PaneModel, columns: number, rows: number): Segment[][] {
  const L = (key: LabelKey) => t(m.lang, key)
  const out: Segment[][] = []
  const blank = () => out.push([{ text: ' ' }])
  const barCells = Math.max(4, Math.min(24, columns - 6))

  // 1. Progress overall
  if (m.run === null) {
    out.push([{ text: L('title'), bold: true }, { text: ': ' + L('noRun'), dim: true }])
  } else {
    const r = m.run
    out.push([{ text: r.title, bold: true }])
    if (r.path !== null) out.push([{ text: r.path, dim: true }])
    out.push([{ text: bar(r.percent, barCells) }, { text: ' ' + pct(r.percent), bold: true }])
    if (r.startedAt !== null && r.elapsedMs !== null) {
      out.push([{ text: `${L('started')} ${hm(r.startedAt)} · ${L('elapsed')} ${dur(r.elapsedMs)}`, dim: true }])
    }
    blank()

    // 2. Per step
    for (const step of r.steps) {
      const name = L(`step.${step.id}` as LabelKey)
      const head: Segment = { text: `${STEP_MARKS[step.status]} ${name}`, bold: step.status === 'active', dim: step.status === 'pending' }
      if (step.id === 'tasks' && step.total !== undefined && step.total > 0) {
        const done = step.done ?? 0
        out.push([{ ...head, text: head.text.padEnd(16) }, { text: bar((done / step.total) * 100, 10) }, { text: ` ${done}/${step.total}` }])
        if (r.current !== null) {
          const station = r.current.station === null ? '' : ` · ${r.current.station}`
          out.push([{ text: `    ${L('task')} ${r.current.n}: ${r.current.title}${station}`, dim: true }])
        }
      } else {
        out.push([head])
      }
    }
  }
  blank()

  // 3. Context window
  const c = m.context
  const tokens = c.window === null ? '' : `  ${k(c.tokens)} / ${k(c.window)} ${L('window')}`
  out.push([
    { text: L('context') + ' ', dim: true },
    { text: bar(c.percent, Math.min(12, barCells)), tone: c.tone },
    { text: ' ' + pct(c.percent), tone: c.tone, bold: true },
    { text: tokens, dim: true },
  ])
  out.push([{ text: `${L('threshold')} ${c.warn}% / ${c.critical}%`, dim: true }])
  if (c.spark.length > 0) out.push([{ text: c.spark, tone: c.tone }])
  const compaction = c.lastCompactionAt === null ? L('none') : `${hm(c.lastCompactionAt)} (${c.compactions})`
  out.push([{ text: `${L('lastCompaction')} ${compaction}`, dim: true }])
  const nameCells = Math.max(4, Math.min(22, columns - 6))
  for (const b of c.breakdown) out.push([{ text: `  ${b.name.padEnd(nameCells).slice(0, nameCells)} ${pct(b.percent).padStart(4)}` }])
  blank()

  // 4. Agents, newest first
  out.push([{ text: L('agents'), bold: true }, { text: ` · ${m.running} ${L('agent.running')} · ${L('context')} ${L('approx')}`, dim: true }])
  const cap = Math.max(1, rows - NON_AGENT_ROWS)
  const typeCells = Math.max(4, columns - AGENT_FIXED)
  for (const a of m.agents.slice(0, cap)) {
    const type = a.type.length > typeCells ? a.type.slice(0, typeCells - 1) + '…' : a.type.padEnd(typeCells)
    const text = [
      `${a.mark} ${a.status.padEnd(8).slice(0, 8)} ${type}`,
      a.model.padEnd(10).slice(0, 10),
      pct(a.ctxPercent).padStart(4),
      `${k(a.tokensIn)}/${k(a.tokensOut)}`.padStart(8),
      dur(a.elapsedMs).padStart(6),
    ].join(' ')
    out.push([{ text, dim: a.isFinished }])
  }
  if (m.agents.length > cap) out.push([{ text: L('more').replace('{n}', String(m.agents.length - cap)), dim: true }])

  // 5. Tokens and cost
  if (m.cost !== null) {
    blank()
    const cost = m.cost
    out.push([{ text: `${L('tokens')} · ${L('cost')}`, bold: true }])
    out.push([{ text: (cost.isEngine ? '' : '~') + usd(cost.usd), bold: true }, { text: '  ' + L(cost.isEngine ? 'costEngine' : 'costEstimate'), dim: true }])
    for (const x of cost.models) {
      out.push([{ text: `${x.name.padEnd(11)}${k(x.input)} ${L('in')} · ${k(x.output)} ${L('out')} · ~${usd(x.usd)}` }])
      out.push([{ text: `${''.padEnd(11)}${k(x.cacheRead)} ${L('cacheRead')} · ${k(x.cacheWrite)} ${L('cacheWrite')}`, dim: true }])
    }
    const hit = cost.cacheHit === null ? '' : `${L('cacheHit')} ${pct(cost.cacheHit)} · `
    out.push([{ text: `${hit}~ ${L('costEstimate')}`, dim: true }])
  }

  // 6. Remaining time
  if (m.run !== null) {
    blank()
    const e = m.run.eta
    const value = e === null
      ? L('notEnoughData')
      : `~${minutes(e.lowMs)}–${minutes(e.highMs)} ${L('min')} · ${Math.max(1, minutes(e.perTaskMs))} ${L('min')} ${L('perTask')}`
    out.push([{ text: L('eta') + '  ', dim: true }, { text: value }])
  }

  return out.map(row => clip(row, columns))
}

/** The pane: one Box per planned row, each a run of Texts. */
export function renderPane(els: ElementTable, rows: Segment[][]): RenderElement {
  const { Box, Text } = els
  return (
    <Box flexDirection="column">
      {rows.map((row, i) => (
        <Box key={`row-${i}`} flexDirection="row">
          {row.map(s => (
            <Text {...styleOf(s)}>{s.text}</Text>
          ))}
        </Box>
      ))}
    </Box>
  )
}

/** The band's content as one line of text, prefixed `SuperMod`, whether the band is hidden or not. */
export function statusText(s: BandState, o: UiOptions): string {
  const m = bandModelOf({ ...s, ui: { ...s.ui, isHidden: false, options: o } })
  const L = (key: LabelKey) => t(o.language, key)
  // No run: the status still names the context and the agent count, from the model rather than the row.
  if (m.percent === null) return `${L('title')}: ${L('noRun')}  ${L('ctx')} ${pct(m.ctxPercent)}  ${L('agents')} ${m.agentsRunning}`
  return `${L('title')}  ${planBandRow(m, 10_000).segments.map(x => x.text).join('')}`
}

files.hooks/scan.ts:
// ── Search roots, path guard and run discovery ────────────────────────────
// Decides which files the mod may ever look at (spec §5.1, §7). Pure apart
// from the Fs port that register.tsx fills. Every list and read, and every stat
// but two, goes through `guard`: the path must lie inside a search root, match
// one of the allowed shapes below for the access asked for, exist, and its
// realPath must be present and match the same shape inside a search root (a
// symlink out, or an answer without realPath, is refused).
// The three documented exceptions are the raw stats in `resolveRoots`: the
// project root itself (to learn its realPath), `<project root>/.git` (a file
// marks a linked worktree) and `<main checkout>/.git` (to confirm the main
// checkout is one); all are stat only, never read or listed.
// Paths are POSIX strings; `..` that climbs above `/` is refused.
// Each file is parsed as it is read and only the parsed value is kept (the
// state never holds a file's text); given the run as last found, a file whose
// stat answers the same mtime as when it was read is not read again (§5.1).

import type { RunFiles, StoredLedger, StoredPlan } from '../types'
import { parseLedger, parsePlan, specTitle } from './progress'
import type { Ledger, Plan } from './progress'

export type FsKind = 'file' | 'dir' | 'other'
export type FsEntry = { name: string; kind: FsKind; mtimeMs: number }
export type FsStat = { kind: FsKind; mtimeMs: number; realPath?: string }
export type Fs = {
  read(path: string): Promise<string>
  list(path: string): Promise<FsEntry[]>
  /**
   * Resolves null when the path is missing. Must be called with resolution on
   * (the engine's `stat(path, { resolve: true })`) so the answer carries
   * `realPath`; an answer without a string `realPath` is treated as leading nowhere.
   */
  stat(path: string): Promise<FsStat | null>
}

export type DiscoverOptions = {
  pinned: string | null
  sessionSpec: string | null
  now: number
  maxAgeMs: number
  /** The run as last found: a file it read whose mtime is unchanged keeps its parsed value, unread. */
  prior?: RunFiles | null
}

const PLAN_HEADINGS_ONLY_ABOVE = 1_048_576
/** Titles kept for the band and pane (§7: at most 80 characters of any title). */
const TITLE_CAP = 80
/** A path named inside a file (marker, ledger header, Spec line) longer than this is ignored. */
const PATH_CAP = 1_024
const WORKTREE_FOLDERS = [['.claude', 'worktrees'], ['.worktrees'], ['worktrees']]

// ── Paths ─────────────────────────────────────────────────────────────────

/** Absolute path without `.`, `..`, empty segments or a trailing slash; null when relative or climbing above `/`. */
function normalize(path: string): string | null {
  if (!path.startsWith('/')) return null
  const out: string[] = []
  for (const seg of path.split('/')) {
    if (seg === '' || seg === '.') continue
    if (seg === '..') {
      if (out.length === 0) return null
      out.pop()
    } else out.push(seg)
  }
  return '/' + out.join('/')
}

function join(root: string, ...parts: string[]): string {
  return [root, ...parts].join('/')
}

function dirname(path: string): string {
  return path.slice(0, path.lastIndexOf('/')) || '/'
}

function basename(path: string): string {
  return path.slice(path.lastIndexOf('/') + 1)
}

/** A listing name that stays one segment when joined to its folder. */
function isPlainName(name: unknown): name is string {
  return typeof name === 'string' && name !== '' && name !== '.' && name !== '..' && !name.includes('/')
}

/** Normalized absolute roots; `/` is never a root. */
function cleanRoots(roots: string[]): string[] {
  const out: string[] = []
  for (const r of roots) {
    const n = normalize(r)
    if (n !== null && n !== '/' && !out.includes(n)) out.push(n)
  }
  return out
}

function relSegments(path: string, root: string): string[] | null {
  if (path === root) return []
  return path.startsWith(root + '/') ? path.slice(root.length + 1).split('/') : null
}

export function isInsideRoots(realPath: string, roots: string[]): boolean {
  const path = normalize(realPath)
  return path !== null && cleanRoots(roots).some(r => relSegments(path, r) !== null)
}

/**
 * The project root, plus the main checkout when the root is itself a worktree
 * (`…/.claude/worktrees/<n>`, `…/.worktrees/<n>`, `…/worktrees/<n>`; the last such segment wins).
 */
export function searchRoots(projectRoot: string): string[] {
  const root = normalize(projectRoot)
  if (root === null) return []
  const segs = root.split('/').slice(1)
  for (let i = segs.length - 2; i >= 0; i--) {
    let cut = -1
    if (segs[i] === '.worktrees') cut = i
    else if (segs[i] === 'worktrees') cut = i > 0 && segs[i - 1] === '.claude' ? i - 1 : i
    if (cut < 0) continue
    const main = '/' + segs.slice(0, cut).join('/')
    return main === '/' ? [root] : [root, main]
  }
  return [root]
}

/**
 * The search roots for a session: the project root resolved through `stat`
 * (lexical when the stat fails or has no realPath), plus the main checkout from
 * `searchRoots` when the root is a linked worktree (`<root>/.git` is a file)
 * and `<main>/.git` exists. A clone of its own inside a `worktrees` folder (its
 * `.git` a folder) never adds the folder above it. `/` is never a root.
 */
export async function resolveRoots(fs: Fs, projectRoot: string): Promise<string[]> {
  const lexical = normalize(projectRoot)
  if (lexical === null) return []
  const stat = await attempt(() => fs.stat(lexical), null)
  const real = stat && typeof stat.realPath === 'string' ? normalize(stat.realPath) : null
  const root = real ?? lexical
  if (root === '/') return []
  const main = searchRoots(root)[1]
  if (main === undefined) return [root]
  const own = await attempt(() => fs.stat(join(root, '.git')), null)
  if (!own || own.kind !== 'file') return [root]
  const git = await attempt(() => fs.stat(join(main, '.git')), null)
  return git ? [root, main] : [root]
}

// ── Allowed shapes and the guard ──────────────────────────────────────────

type Shape = 'plans' | 'specs' | 'sdd' | 'workspace' | 'plan' | 'spec' | 'ledger' | 'marker' | 'worktrees'

/** What a path relative to a root is allowed to be, if anything. */
function shapeOf(s: string[]): Shape | null {
  const docs = s.length >= 3 && s[0] === 'docs' && s[1] === 'superpowers'
  const sdd = s.length >= 2 && s[0] === '.superpowers' && s[1] === 'sdd'
  if (docs && s.length === 3 && s[2] === 'plans') return 'plans'
  if (docs && s.length === 3 && s[2] === 'specs') return 'specs'
  if (docs && s.length === 4 && s[2] === 'plans' && s[3].endsWith('.md') && s[3].length > 3) return 'plan'
  if (docs && s.length === 4 && s[2] === 'specs' && s[3].endsWith('-design.md') && s[3].length > 10) return 'spec'
  if (sdd && s.length === 2) return 'sdd'
  if (sdd && s.length === 3) return 'workspace'
  if (sdd && s.length === 4 && s[3] === 'progress.md') return 'ledger'
  if (sdd && s.length === 4 && s[3] === 'plan-path') return 'marker'
  if (WORKTREE_FOLDERS.some(f => f.length === s.length && f.every((x, i) => x === s[i]))) return 'worktrees'
  return null
}

/** The root under which `path` has `shape`, or null. */
function rootFor(path: string, roots: string[], shape: Shape): string | null {
  for (const r of roots) {
    const s = relSegments(path, r)
    if (s !== null && shapeOf(s) === shape) return r
  }
  return null
}

/** The first root under which `path` has any allowed shape. */
function locate(path: string, roots: string[]): { root: string; shape: Shape } | null {
  for (const r of roots) {
    const s = relSegments(path, r)
    const shape = s === null ? null : shapeOf(s)
    if (shape !== null) return { root: r, shape }
  }
  return null
}

async function attempt<T>(fn: () => Promise<T>, fallback: T): Promise<T> {
  try {
    return await fn()
  } catch {
    return fallback
  }
}

type Guard = { fs: Fs; roots: string[]; prior: RunFiles | null }
type Admitted = { path: string; root: string; stat: FsStat }

/** The gate to the Fs: shape inside a root, exists, realPath present and of the same shape inside a root. */
async function guard(g: Guard, path: string, shape: Shape): Promise<Admitted | null> {
  const norm = normalize(path)
  if (norm === null) return null
  const root = rootFor(norm, g.roots, shape)
  if (root === null) return null
  const stat = await attempt(() => g.fs.stat(norm), null)
  if (!stat) return null
  if (typeof stat.realPath !== 'string') return null
  const real = normalize(stat.realPath)
  if (real === null || rootFor(real, g.roots, shape) === null) return null
  return { path: norm, root, stat }
}

/** Entries of an admitted folder; null when refused or missing. */
async function listDir(g: Guard, path: string, shape: Shape): Promise<{ path: string; entries: FsEntry[] } | null> {
  const ok = await guard(g, path, shape)
  if (!ok || ok.stat.kind !== 'dir') return null
  const entries = await attempt(() => g.fs.list(ok.path), [] as FsEntry[])
  return { path: ok.path, entries: Array.isArray(entries) ? entries.filter(e => e !== null && typeof e === 'object' && isPlainName(e.name)) : [] }
}

type Loaded = { path: string; root: string; mtimeMs: number; text: string | null; prior: RunFiles | null }

/**
 * An admitted file; null when refused or missing. When the prior run read this
 * same file (`pathOf` names it there) at the mtime the stat answers now, that
 * run is handed back as `prior` and nothing is read; otherwise the text, null
 * when the read fails.
 */
async function load(g: Guard, path: string, shape: Shape, pathOf: (r: RunFiles) => string | null): Promise<Loaded | null> {
  const ok = await guard(g, path, shape)
  if (!ok || ok.stat.kind !== 'file') return null
  const at = { path: ok.path, root: ok.root, mtimeMs: ok.stat.mtimeMs }
  const p = g.prior
  if (p !== null && pathOf(p) === ok.path && p.stamps.some(s => s.path === ok.path && s.mtimeMs === at.mtimeMs)) return { ...at, text: null, prior: p }
  const text = await attempt(() => g.fs.read(ok.path), null)
  return { ...at, text: typeof text === 'string' ? text : null, prior: null }
}

/** The loaded file's value, the prior run's when unchanged; a file read or kept is stamped with its mtime. */
function parsed<T>(run: RunFiles, f: Loaded, valueOf: (r: RunFiles) => T | null, parse: (text: string) => T | null): T | null {
  const value = f.prior !== null ? valueOf(f.prior) : f.text !== null ? parse(f.text) : null
  if ((f.prior !== null || f.text !== null) && Number.isFinite(f.mtimeMs)) run.stamps.push({ path: f.path, mtimeMs: f.mtimeMs })
  return value
}

const capTitle = (t: string) => (t.length > TITLE_CAP ? t.slice(0, TITLE_CAP - 1) + '…' : t)
const capPath = (p: string | null) => (p !== null && p.length <= PATH_CAP ? p : null)

const storeLedger = (l: Ledger): StoredLedger => ({ planPath: capPath(l.planPath), tasks: [...l.tasks.values()] })

const storePlan = (p: Plan): StoredPlan => ({
  title: capTitle(p.title),
  specPath: capPath(p.specPath),
  tasks: [...p.taskTitles].map(([n, title]) => ({ n, title: capTitle(title) })),
})

/** The prior run when it carries stamps (state written by an older version does not). */
const usable = (prior: RunFiles | null | undefined): RunFiles | null =>
  prior !== null && typeof prior === 'object' && Array.isArray(prior.stamps) ? prior : null

// ── Run assembly ──────────────────────────────────────────────────────────

const emptyRun = (): RunFiles => ({
  root: null, ledgerPath: null, ledger: null, marker: null, planPath: null, plan: null,
  specPath: null, specTitle: null, workspaceDir: null, workspaceFiles: [], workspaceExists: false, stamps: [],
})

const foundAnything = (r: RunFiles) => r.ledgerPath !== null || r.planPath !== null || r.specPath !== null || r.workspaceExists

/** A path from a marker, Spec line or option: absolute as given, relative against `base`. */
function resolveAgainst(base: string, ref: string): string | null {
  return normalize(ref.startsWith('/') ? ref : join(base, ref))
}

/** A plan over 1 MiB keeps only headings, fence lines (so code stays code) and the Spec line. */
function trimPlan(text: string): string {
  if (text.length <= PLAN_HEADINGS_ONLY_ABOVE) return text
  return text
    .split(/\r?\n/)
    .filter(l => l.startsWith('#') || l.startsWith('**Spec:**') || l.trimStart().startsWith('```'))
    .join('\n')
}

async function withPlan(g: Guard, run: RunFiles, planPath: string): Promise<void> {
  const plan = await load(g, planPath, 'plan', r => r.planPath)
  if (!plan) return
  run.planPath = plan.path
  run.plan = parsed(run, plan, r => r.plan, text => storePlan(parsePlan(trimPlan(text), basename(plan.path))))
  const ref = run.plan?.specPath ?? null
  if (ref === null) return
  // Relative to the plan's folder first (a Markdown link), then to its root.
  for (const base of [dirname(plan.path), plan.root]) {
    const specPath = resolveAgainst(base, ref)
    if (specPath !== null) await withSpec(g, run, specPath)
    if (run.specPath !== null) return
  }
}

async function withSpec(g: Guard, run: RunFiles, specPath: string): Promise<void> {
  const spec = await load(g, specPath, 'spec', r => r.specPath)
  if (!spec) return
  run.specPath = spec.path
  run.specTitle = parsed(run, spec, r => r.specTitle, text => capTitle(specTitle(text, basename(spec.path))))
}

async function withWorkspace(g: Guard, run: RunFiles, dir: string): Promise<void> {
  const ws = await listDir(g, dir, 'workspace')
  if (!ws) return
  run.workspaceDir = ws.path
  run.workspaceExists = true
  run.workspaceFiles = ws.entries.filter(e => e.kind === 'file').map(e => ({ name: e.name, mtimeMs: e.mtimeMs }))
  const ledger = await load(g, join(ws.path, 'progress.md'), 'ledger', r => r.ledgerPath)
  if (ledger) {
    run.ledgerPath = ledger.path
    run.ledger = parsed(run, ledger, r => r.ledger, text => storeLedger(parseLedger(text)))
  }
}

/** Ledger, marker, plan and spec of one workspace; the marker names the plan, the ledger header is the fallback. */
async function runFromWorkspace(g: Guard, root: string, dir: string): Promise<RunFiles> {
  const run = { ...emptyRun(), root }
  await withWorkspace(g, run, dir)
  if (!run.workspaceExists) return run
  const marker = await load(g, join(dir, 'plan-path'), 'marker', r => (r.workspaceDir === null ? null : join(r.workspaceDir, 'plan-path')))
  if (marker) run.marker = parsed(run, marker, r => r.marker, text => capPath(text.split(/\r?\n/)[0].trim() || null))
  const ref = run.marker ?? run.ledger?.planPath ?? null
  const planPath = ref ? resolveAgainst(root, ref) : null
  if (planPath !== null) await withPlan(g, run, planPath)
  return run
}

/** A plan, its spec, and its workspace `.superpowers/sdd/<plan basename>/` when present. */
async function runFromPlan(g: Guard, root: string, planPath: string): Promise<RunFiles> {
  const run = { ...emptyRun(), root }
  await withPlan(g, run, planPath)
  if (run.planPath === null) return run
  await withWorkspace(g, run, join(root, '.superpowers', 'sdd', basename(run.planPath).slice(0, -'.md'.length)))
  return run
}

async function runFromSpec(g: Guard, root: string, specPath: string): Promise<RunFiles> {
  const run = { ...emptyRun(), root }
  await withSpec(g, run, specPath)
  return run
}

/** The run a pinned path names: a workspace (or its ledger or marker), a plan, or a spec. */
async function runFromPinned(g: Guard, pinned: string): Promise<RunFiles | null> {
  const path = resolveAgainst(g.roots[0], pinned)
  const at = path === null ? null : locate(path, g.roots)
  if (path === null || at === null) return null
  if (at.shape === 'workspace') return runFromWorkspace(g, at.root, path)
  if (at.shape === 'ledger' || at.shape === 'marker') return runFromWorkspace(g, at.root, dirname(path))
  if (at.shape === 'plan') return runFromPlan(g, at.root, path)
  if (at.shape === 'spec') return runFromSpec(g, at.root, path)
  return null
}

type Candidate = { root: string; path: string; mtimeMs: number }

const newest = (cs: Candidate[]): Candidate | null => cs.reduce<Candidate | null>((best, c) => (best === null || c.mtimeMs > best.mtimeMs ? c : best), null)

async function freshLedgers(g: Guard, fresh: (mtimeMs: number) => boolean): Promise<Candidate[]> {
  const out: Candidate[] = []
  for (const root of g.roots) {
    const sdd = await listDir(g, join(root, '.superpowers', 'sdd'), 'sdd')
    if (!sdd) continue
    for (const e of sdd.entries) {
      if (e.kind !== 'dir') continue
      const ledger = await guard(g, join(sdd.path, e.name, 'progress.md'), 'ledger')
      if (ledger && ledger.stat.kind === 'file' && fresh(ledger.stat.mtimeMs)) {
        out.push({ root, path: join(sdd.path, e.name), mtimeMs: ledger.stat.mtimeMs })
      }
    }
  }
  return out
}

async function freshPlans(g: Guard, fresh: (mtimeMs: number) => boolean): Promise<Candidate[]> {
  const out: Candidate[] = []
  for (const root of g.roots) {
    const plans = await listDir(g, join(root, 'docs', 'superpowers', 'plans'), 'plans')
    if (!plans) continue
    for (const e of plans.entries) {
      if (e.kind === 'file' && e.name.endsWith('.md') && fresh(e.mtimeMs)) out.push({ root, path: join(plans.path, e.name), mtimeMs: e.mtimeMs })
    }
  }
  return out
}

/**
 * The current run: pinned path → newest ledger in the age window → spec written
 * this session → newest plan in the age window → nothing. Never throws.
 */
export async function discoverRun(fs: Fs, roots: string[], opts: DiscoverOptions): Promise<RunFiles> {
  const g: Guard = { fs, roots: cleanRoots(roots), prior: usable(opts.prior) }
  if (g.roots.length === 0) return emptyRun()
  const fresh = (mtimeMs: number) => opts.now - mtimeMs <= opts.maxAgeMs

  if (opts.pinned) {
    const run = await runFromPinned(g, opts.pinned)
    if (run && foundAnything(run)) return run
  }
  const ledger = newest(await freshLedgers(g, fresh))
  if (ledger) return runFromWorkspace(g, ledger.root, ledger.path)
  if (opts.sessionSpec) {
    const path = resolveAgainst(g.roots[0], opts.sessionSpec)
    const root = path === null ? null : rootFor(path, g.roots, 'spec')
    if (path !== null && root !== null) {
      const run = await runFromSpec(g, root, path)
      if (foundAnything(run)) return run
    }
  }
  const plan = newest(await freshPlans(g, fresh))
  if (plan) return runFromPlan(g, plan.root, plan.path)
  return emptyRun()
}

/** Folders under the main checkout's worktree folders (names only), as further search roots. */
export async function discoverWorktreeRoots(fs: Fs, mainRoot: string): Promise<string[]> {
  const g: Guard = { fs, roots: cleanRoots([mainRoot]), prior: null }
  if (g.roots.length === 0) return []
  const out: string[] = []
  for (const folder of WORKTREE_FOLDERS) {
    const listed = await listDir(g, join(g.roots[0], ...folder), 'worktrees')
    if (!listed) continue
    for (const e of listed.entries) if (e.kind === 'dir') out.push(join(listed.path, e.name))
  }
  return out
}

